<span class="line"><span style="color:#C792EA;">type</span><span style="color:#FFCB6B;"> CapitalizedGreeting</span><span style="color:#89DDFF;"> =</span><span style="color:#FFCB6B;"> Capitalize</span><span style="color:#89DDFF;">&lt;</span><span style="color:#FFCB6B;">Greeting</span><span style="color:#89DDFF;">&gt;;</span><span style="color:#676E95;font-style:italic;"> // &quot;Hello&quot;</span></span>
